  # Calculate the sum of the first row
  sum_row_1 = sum(square[0])

  # Check if all rows have the same sum
  for row in square:
      if sum(row) != sum_row_1:
          return False

  # Check if all columns have the same sum
  for col in range(len(square)):
      column_sum = sum(square[row][col] for row in range(len(square)))
      if column_sum != sum_row_1:
          return False

  # Check if the main diagonal has the same sum
  main_diagonal_sum = sum(square[i][i] for i in range(len(square)))
  if main_diagonal_sum != sum_row_1:
      return False

  # Check if the secondary diagonal has the same sum
  secondary_diagonal_sum = sum(square[i][len(square)-1-i] for i in range(len(square)))
  if secondary_diagonal_sum != sum_row_1:
      return False

  # If all checks pass, it's a magic square
  return True

